# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN-I KERİM\'İ TANIYORUM: TEMEL ARAPÇA KAVRAMLAR</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. Vahiy ve Mushaf</text>\n  <rect x="34" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">el-Kur\'ânü\'l-Kerîm / el-Mushaf</text>\n  <text x="32" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold">el-Vahy:</tspan> İlahi bildirim, vahiy</text>\n  <text x="32" y="148" font-size="10" fill="#334155">• <tspan font-weight="bold">el-Mushaf:</tspan> İki kapak arasındaki</text>\n  <text x="40" y="163" font-size="10" fill="#334155">yazılı Kur\'an nüshası</text>\n  <text x="32" y="183" font-size="10" fill="#334155">• <tspan font-weight="bold">el-Hidâye:</tspan> Doğru yola rehberlik</text>\n  <text x="32" y="203" font-size="10" fill="#334155">• <tspan font-weight="bold">Rabbü\'l-Âlemîn:</tspan> Âlemlerin</text>\n  <text x="40" y="218" font-size="10" fill="#334155">Rabbi olan Yüce Allah</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. İç Düzen Birimleri</text>\n  <rect x="259" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">Âyet (Âyât) · Sûre · Cüz\'</text>\n  <text x="257" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold">Âye (Çoğulu: Âyât):</tspan> Sureleri</text>\n  <text x="265" y="143" font-size="10" fill="#334155">oluşturan her bir ilahi cümle</text>\n  <text x="257" y="163" font-size="10" fill="#334155">• <tspan font-weight="bold">Sûre (Çoğulu: Süver):</tspan> Mushafta</text>\n  <text x="265" y="178" font-size="10" fill="#334155">114 bağımsız bölüm vardır.</text>\n  <text x="257" y="198" font-size="10" fill="#334155">• <tspan font-weight="bold">el-Cüz\' (Çoğulu: Eczâ\'):</tspan></text>\n  <text x="265" y="213" font-size="10" fill="#334155">20 sayfalık bölüm (Toplam 30 cüz)</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">3. Temel Fiil Kalıpları</text>\n  <rect x="484" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">Tetekevvenü min / Enzele</text>\n  <text x="482" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold">eta\'arrafü alâ:</tspan> ...\'yı tanıyorum</text>\n  <text x="482" y="148" font-size="10" fill="#334155">• <tspan font-weight="bold">yetekevvenü min:</tspan> ...\'dan oluşur</text>\n  <text x="482" y="168" font-size="10" fill="#334155">• <tspan font-weight="bold">enzele / نَزَلَ:</tspan> İndirdi / İndi</text>\n  <text x="482" y="188" font-size="10" fill="#334155">• <tspan font-weight="bold">yahtevî alâ:</tspan> ...\'yı içerir, kapsar</text>\n  <text x="482" y="208" font-size="10" fill="#334155">• <tspan font-weight="bold">yed\'û ilâ:</tspan> ...\'ya davet eder</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MEKKÎ - MEDENÎ SURELER, TEVHİT DAVETİ VE KUR\'AN KISSALARI</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#5b21b6">1. Surelerin Sınıflandırılması ve Özellikleri</text>\n  <rect x="34" y="78" width="292" height="46" rx="6" fill="#ffffff" stroke="#8b5cf6" stroke-width="1.5"/>\n  <text x="44" y="96" font-size="10.5" font-weight="bold" fill="#5b21b6">• es-Süveru\'l-Mekkiyye (el-Mekkî):</text>\n  <text x="52" y="113" font-size="10" fill="#334155">Hicretten önce inen, tevhit ve ahireti vurgulayan sureler.</text>\n  <rect x="34" y="132" width="292" height="46" rx="6" fill="#ffffff" stroke="#8b5cf6" stroke-width="1.5"/>\n  <text x="44" y="150" font-size="10.5" font-weight="bold" fill="#5b21b6">• es-Süveru\'l-Medeniyye (el-Medenî):</text>\n  <text x="52" y="167" font-size="10" fill="#334155">Hicretten sonra inen, ibadet ve toplumsal hükümleri içerenler.</text>\n  <text x="34" y="200" font-size="10.5" font-weight="bold" fill="#4c1d95">• el-Hurûfü\'l-Mukattaa:</text>\n  <text x="42" y="216" font-size="10" fill="#334155">Yirmi dokuz surenin başında yer alan kesik harfler.</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Kur\'an\'ın Konuları ve Kıssalar (el-Kasas)</text>\n  <text x="374" y="92" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">el-Ubûdiyye (Kulluk):</tspan> Yalnız Allah\'a ibadet etmek.</text>\n  <text x="374" y="114" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">ed-Da\'ve (Davet):</tspan> İnsanları tevhide ve hidayete çağrı.</text>\n  <text x="374" y="136" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">el-Esnâm (Putlar):</tspan> Şirk unsuru olan cansız putların reddi.</text>\n  <text x="374" y="158" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">el-Kasas (Kıssalar):</tspan> Peygamberlerin ve geçmiş</text>\n  <text x="382" y="173" font-size="10" fill="#475569">toplulukların ibret verici hakikatli haberleri.</text>\n  <rect x="374" y="186" width="292" height="38" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="520" y="203" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Halîlullâh (Allah\'ın Dostu): Hz. İbrahim (a.s.)</text>\n  <text x="520" y="218" text-anchor="middle" font-size="9.5" fill="#334155">Putları (el-esnâm) kırarak tevhit mücadelesi vermiştir.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TİLAVET KAVRAMLARI (TECVİT, MUKABELE, HATİM) VE CÜMLE KALIPLARI</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. et-Tecvîd (Tecvit İlmi)</text>\n  <rect x="34" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">التَّجْوِيدُ : تَحْسِينُ الْقِرَاءَةِ</text>\n  <text x="32" y="128" font-size="10" fill="#334155">• Harfleri mahrecinden ve</text>\n  <text x="40" y="143" font-size="10" fill="#334155">sıfatlarına uygun okumaktır.</text>\n  <text x="32" y="168" font-size="10" font-weight="bold" fill="#1e40af">• Örnek Cümle:</text>\n  <text x="32" y="186" font-size="10" fill="#334155">Yekra\'ü\'l-müslimü\'l-Kur\'âne</text>\n  <text x="32" y="201" font-size="10" fill="#334155">bi-ahkâmi\'t-tecvîdi.</text>\n  <text x="32" y="218" font-size="9.5" fill="#475569">(Müslüman Kur\'an\'ı tecvit ile okur.)</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Hatmü\'l-Kur\'ân (Hatim)</text>\n  <rect x="259" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">خَتْمُ الْقُرْآنِ الْكَرِيمِ</text>\n  <text x="257" y="128" font-size="10" fill="#334155">• Mushafı Fâtiha suresinden</text>\n  <text x="265" y="143" font-size="10" fill="#334155">Nâs suresine kadar baştan</text>\n  <text x="265" y="158" font-size="10" fill="#334155">sona okuyup bitirmektir.</text>\n  <text x="257" y="182" font-size="10" font-weight="bold" fill="#15803d">• Örnek İfade:</text>\n  <text x="257" y="198" font-size="10" fill="#334155">Min sûreti\'l-Fâtihati ilâ</text>\n  <text x="257" y="213" font-size="10" fill="#334155">sûreti\'n-Nâsi (Fâtiha\'dan Nâs\'a).</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">3. el-Mukâbele (Mukabele)</text>\n  <rect x="484" y="78" width="182" height="32" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="575" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">الْمُقَابَلَةُ فِي شَهْرِ رَمَضَانَ</text>\n  <text x="482" y="128" font-size="10" fill="#334155">• Karşılıklı Kur\'an okuma ve</text>\n  <text x="490" y="143" font-size="10" fill="#334155">dinleme sünnetidir.</text>\n  <text x="482" y="168" font-size="10" font-weight="bold" fill="#92400e">• Kaynağı:</text>\n  <text x="482" y="186" font-size="10" fill="#334155">Cebrâil (a.s.) ile Hz. Peygamber\'in</text>\n  <text x="482" y="201" font-size="10" fill="#334155">ramazan ayında Kur\'an\'ı karşılıklı</text>\n  <text x="482" y="216" font-size="10" fill="#334155">okumalarına dayanır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
